        case proofId = "proof_id"
        case uploadUrl = "upload_url"
        case uploadMethod = "upload_method"
        case uploadHeaders = "upload_headers"
        case uploadExpiresAt = "upload_expires_at"
    }
}

public struct Proof: Codable, Hashable, Sendable {
    public let id: UUID
    public let weekId: UUID
    public let memberId: UUID
    public let kind: ProofKind
    public let durationMs: Int?
    public let createdAt: Date

    /// When the bytes are deleted server-side. Enforced by a sweep plus a storage
    /// lifecycle rule, and asserted by a test — the user was promised this.
    public let expiresAt: Date

    /// Short-lived, single-pod-scoped. Expires long before `expires_at`.
    public let viewUrl: URL?
    public let viewUrlExpiresAt: Date?

    public init(
        id: UUID,
        weekId: UUID,
        memberId: UUID,
        kind: ProofKind,
        durationMs: Int? = nil,
        createdAt: Date,
        expiresAt: Date,
        viewUrl: URL? = nil,
        viewUrlExpiresAt: Date? = nil
    ) {
        self.id = id
        self.weekId = weekId
        self.memberId = memberId
        self.kind = kind
        self.durationMs = durationMs
        self.createdAt = createdAt
        self.expiresAt = expiresAt
        self.viewUrl = viewUrl
        self.viewUrlExpiresAt = viewUrlExpiresAt
    }

    private enum CodingKeys: String, CodingKey {
        case id
        case weekId = "week_id"
        case memberId = "member_id"
        case kind
        case durationMs = "duration_ms"
        case createdAt = "created_at"
        case expiresAt = "expires_at"
        case viewUrl = "view_url"
        case viewUrlExpiresAt = "view_url_expires_at"
    }
}
